"""Writes corpus_texts.json (the plain texts for the load generator)."""
import json
SHORT = ["Welcome back.","Your order has shipped.","The meeting starts in five minutes.","Please hold while I connect you.","Thanks for calling, goodbye.","The forecast calls for light rain.","Your appointment is confirmed for Tuesday.","Press one to continue."]
MEDIUM = ["The library closes at nine on weekdays, so there is still time to return the books you borrowed last month.","After the update installs, the device restarts twice; do not unplug it until the light stops blinking.","Our support team has received your request and will reply within two business days with the next steps.","The trail follows the river for three miles before climbing steadily toward the ridge and the old fire tower.","To change your delivery address, open the orders page, select the pending shipment, and choose the edit option.","The orchestra returns this season with a program of early symphonies and a newly commissioned piece for strings."]
LONG = ["The committee reviewed the proposal in detail during the afternoon session, weighing the projected costs against the expected benefits for each of the three districts involved. Several members raised questions about the maintenance schedule, and the engineers agreed to provide a revised estimate before the next meeting. In the meantime, the temporary measures adopted last spring will remain in effect, and residents will continue to receive weekly updates through the usual channels.","When the harbor was first dredged more than a century ago, the town's economy depended almost entirely on the fishing fleet, and every family kept at least one small boat along the shore. Over the decades the wharves gave way to warehouses, the warehouses to workshops, and the workshops to the quiet row of studios and cafes that visitors photograph today. What has not changed is the morning light on the water, which still arrives at the same angle it always has, and still empties the streets as everyone turns to look."]
json.dump([{"text": t} for t in SHORT + MEDIUM + LONG], open("/work/corpus_texts.json", "w"), indent=1)
print("texts:", len(SHORT + MEDIUM + LONG))
